 17	/** Serves the given SSE frames as a streaming Response body. */
 18	function sseResponse(frames: string[], init?: ResponseInit): Response {
 19	  const body = new ReadableStream<Uint8Array>({
 20	    start(controller) {
 21	      const encoder = new TextEncoder();
 22	      for (const frame of frames) controller.enqueue(encoder.encode(frame));
 23	      controller.close();
 24	    },
 25	  });
 26	  return new Response(body, { headers: { "Content-Type": "text/event-stream" }, ...init });
 27	}
