12	function isRecord(value: unknown): value is Record<string, unknown> {
13	  return typeof value === "object" && value !== null && !Array.isArray(value);
14	}
15	
16	function isFiniteNumber(value: unknown): value is number {
17	  return typeof value === "number" && Number.isFinite(value);
18	}
19	
20	function isProviderId(value: unknown): value is ProviderId {
21	  return ["openai", "anthropic", "google", "openrouter", "custom"].includes(String(value));
22	}
23	
24	function isChatMessage(value: unknown): value is ChatMessage {
25	  if (!isRecord(value)) return false;
26	  return typeof value.id === "string"
27	    && (value.role === "user" || value.role === "assistant")
28	    && typeof value.content === "string"
29	    && isFiniteNumber(value.createdAt)
30	    && (value.feedback === undefined || value.feedback === "helpful" || value.feedback === "missed");
31	}
32	
33	function isChatSession(value: unknown): value is ChatSession {
34	  if (!isRecord(value)) return false;
35	  return typeof value.id === "string"
36	    && typeof value.title === "string"
37	    && isFiniteNumber(value.createdAt)
38	    && isFiniteNumber(value.updatedAt)
39	    && Array.isArray(value.messages)
40	    && value.messages.every(isChatMessage)
41	    && (value.parentSessionId === undefined || typeof value.parentSessionId === "string")
42	    && (value.forkedFromMessageId === undefined || typeof value.forkedFromMessageId === "string")
43	    && (value.forkedAt === undefined || isFiniteNumber(value.forkedAt));
44	}
45	
46	function isArtifact(value: unknown): value is StudyArtifact {
47	  if (!isRecord(value)) return false;
48	  return typeof value.id === "string"
49	    && typeof value.kind === "string"
50	    && typeof value.title === "string"
51	    && typeof value.content === "string"
52	    && isFiniteNumber(value.createdAt);
53	}
54	
55	function isProviderSettings(value: unknown): value is ProviderSettings {
56	  if (!isRecord(value)) return false;
57	  return isProviderId(value.provider)
58	    && typeof value.model === "string"
59	    && typeof value.baseUrl === "string"
60	    && isFiniteNumber(value.temperature);
61	}
62	
63	function isPersistedShape(value: Record<string, unknown>): boolean {
64	  const feedback = value.learnerFeedback;
65	  return Array.isArray(value.sessions)
66	    && value.sessions.every(isChatSession)
67	    && typeof value.activeSessionId === "string"
68	    && Array.isArray(value.artifacts)
69	    && value.artifacts.every(isArtifact)
70	    && isProviderSettings(value.providerSettings)
71	    && isRecord(feedback)
72	    && isFiniteNumber(feedback.helpful)
73	    && isFiniteNumber(feedback.missed);
74	}
