76	/** Validate before migration so malformed local data is never overwritten. */
77	export function migratePersistedState(candidate: unknown): PersistedAppState | null {
78	  if (!isRecord(candidate) || !isPersistedShape(candidate)) return null;
79	  if (candidate.schemaVersion === 2) return candidate as unknown as PersistedAppState;
80	  if (candidate.schemaVersion === 1) {
81	    const legacy = candidate as unknown as PersistedAppStateV1;
82	    return { ...legacy, schemaVersion: 2 };
83	  }
84	  return null;
85	}
