 45	/** Parent-first session ordering with stable, bounded indentation metadata. */
 46	export function buildSessionTreeRows(sessions: readonly ChatSession[]): SessionTreeRow[] {
 47	  const byId = new Map(sessions.map((session) => [session.id, session]));
 48	  const children = new Map<string, ChatSession[]>();
 49	  const roots: ChatSession[] = [];
 50	  const byUpdated = (left: ChatSession, right: ChatSession) => right.updatedAt - left.updatedAt;
 51	
 52	  for (const session of sessions) {
 53	    if (session.parentSessionId && byId.has(session.parentSessionId) && session.parentSessionId !== session.id) {
 54	      const siblings = children.get(session.parentSessionId) ?? [];
 55	      siblings.push(session);
 56	      children.set(session.parentSessionId, siblings);
 57	    } else {
 58	      roots.push(session);
 59	    }
 60	  }
 61	  roots.sort(byUpdated);
 62	  for (const siblings of children.values()) siblings.sort(byUpdated);
 63	
 64	  const rows: SessionTreeRow[] = [];
 65	  const visited = new Set<string>();
 66	  const visit = (session: ChatSession, depth: number) => {
 67	    if (visited.has(session.id)) return;
 68	    visited.add(session.id);
 69	    rows.push({ session, depth });
 70	    for (const child of children.get(session.id) ?? []) visit(child, depth + 1);
 71	  };
 72	  for (const root of roots) visit(root, 0);
 73	  // Malformed cycles stay visible instead of disappearing from the browser.
 74	  for (const session of [...sessions].sort(byUpdated)) visit(session, 0);
 75	  return rows;
 76	}
