 34	export async function refreshModelsDevCatalog(
 35	  fetchImpl: typeof fetch = fetch,
 36	  options: { signal?: AbortSignal; timeoutMs?: number } = {},
 37	): Promise<CatalogModel[]> {
 38	  const controller = new AbortController();
 39	  const timeoutMs = options.timeoutMs ?? 30_000;
 40	  const abortFromCaller = () => controller.abort();
 41	  options.signal?.addEventListener("abort", abortFromCaller, { once: true });
 42	  const timeout = setTimeout(() => controller.abort(), timeoutMs);
 43	  try {
 44	    const response = await fetchImpl(MODELS_DEV_CATALOG_URL, {
 45	      headers: { Accept: "application/json" },
 46	      signal: controller.signal,
 47	    });
 48	    if (!response.ok) throw new Error(`models.dev refresh failed (HTTP ${response.status}).`);
 49	    const models = parseModelsDevCatalog(await response.json());
 50	    const cache: CachedCatalog = { updatedAt: Date.now(), models };
 51	    await AsyncStorage.setItem(CATALOG_CACHE_KEY, JSON.stringify(cache));
 52	    return models;
 53	  } catch (error) {
 54	    if (controller.signal.aborted && !options.signal?.aborted) {
 55	      throw new Error("models.dev refresh timed out. Check the connection and retry.");
 56	    }
 57	    throw error;
 58	  } finally {
 59	    clearTimeout(timeout);
 60	    options.signal?.removeEventListener("abort", abortFromCaller);
 61	  }
 62	}
